/**
 * selftest.js — 独立自测试脚本：
 * 1. 生成 440Hz 标准正弦波 WAV（16bit 44100Hz 单声道 2 秒），验证 F0 误差 < 2Hz。
 * 2. 解码 MPEG-1 Layer 3 音频，验证峰值与 RMS 电平与期望值相差 ≤ 1 dB，时长误差 ≤ 0.1 s。
 * 3. 解码 MPEG-2 Layer 3 音频（24kHz mono 128kbps），验证峰值与 RMS 电平相差 ≤ 1 dB，时长误差 ≤ 0.1 s。
 */
import { writeFileSync, unlinkSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { decodeWav, decodeMp3, computeAcousticMetrics } from './lib/index.js'

// 1. WAV 构造器（440Hz 标准正弦波）
function createSineWav(frequency = 440, durationSeconds = 2, sampleRate = 44100) {
  const numSamples = Math.floor(sampleRate * durationSeconds)
  const bytesPerSample = 2
  const dataSize = numSamples * bytesPerSample
  const buffer = Buffer.alloc(44 + dataSize)

  buffer.write('RIFF', 0)
  buffer.writeUInt32LE(36 + dataSize, 4)
  buffer.write('WAVE', 8)

  buffer.write('fmt ', 12)
  buffer.writeUInt32LE(16, 16)
  buffer.writeUInt16LE(1, 20)
  buffer.writeUInt16LE(1, 22)
  buffer.writeUInt32LE(sampleRate, 24)
  buffer.writeUInt32LE(sampleRate * bytesPerSample, 28)
  buffer.writeUInt16LE(bytesPerSample, 32)
  buffer.writeUInt16LE(16, 34)

  buffer.write('data', 36)
  buffer.writeUInt32LE(dataSize, 40)

  for (let i = 0; i < numSamples; i++) {
    const t = i / sampleRate
    const sampleVal = Math.sin(2 * Math.PI * frequency * t) * 0.8 // -1.94 dBFS
    const int16 = Math.floor(sampleVal * 32767)
    buffer.writeInt16LE(int16, 44 + i * bytesPerSample)
  }

  return buffer
}

// 2. 内嵌真实 MPEG-1 Layer 3 测试片段数据 (Base64)
const SAMPLE_MPEG1_B64 = 
"";

// 3. 内嵌真实 MPEG-2 Layer 3 测试音频数据 (Base64, 24kHz mono 128kbps, 6.05s)
const SAMPLE_MPEG2_B64 = [
  "",
  "",
  "",
  "",
].join('');

async function testWav() {
  console.log('--- [测试 1/3] WAV 440Hz 正弦波基频 F0 测试 ---')
  const testWavPath = join(tmpdir(), `selftest_sine440_${Date.now()}.wav`)
  const wavBuf = createSineWav(440, 2, 44100)
  writeFileSync(testWavPath, wavBuf)

  try {
    const decoded = decodeWav(wavBuf)
    const metrics = computeAcousticMetrics(decoded.samples, decoded.sampleRate)

    console.log(`  采样率: ${decoded.sampleRate} Hz | 声道: ${decoded.channels} | 时长: ${decoded.duration.toFixed(2)} s`)
    console.log(`  计算指标: Peak = ${metrics.peakDbfs} dBFS | RMS = ${metrics.rmsDbfs} dBFS | F0 中位数 = ${metrics.f0Median} Hz`)

    const f0Error = Math.abs(metrics.f0Median - 440)
    console.log(`  F0 误差: ${f0Error.toFixed(2)} Hz (硬性限制 < 2.0 Hz)`)

    if (f0Error >= 2.0) {
      throw new Error(`F0 误差超标: ${f0Error} Hz (期望 440Hz，实测 ${metrics.f0Median}Hz)`)
    }
    console.log('  ✔ [PASS] WAV 440Hz F0 测试通过！\n')
  } finally {
    try { unlinkSync(testWavPath) } catch (_) {}
  }
}

async function testMpeg1() {
  console.log('--- [测试 2/3] MPEG-1 Layer 3 解码与真实电平比对测试 ---')
  const mp3Buf = Buffer.from(SAMPLE_MPEG1_B64, 'base64')
  const testMp3Path = join(tmpdir(), `selftest_sample_mpeg1_${Date.now()}.mp3`)
  writeFileSync(testMp3Path, mp3Buf)

  try {
    const t0 = performance.now()
    const decoded = decodeMp3(mp3Buf)
    const t1 = performance.now()
    const metrics = computeAcousticMetrics(decoded.samples, decoded.sampleRate)

    console.log(`  解码耗时: ${(t1 - t0).toFixed(2)} ms`)
    console.log(`  格式: ${decoded.channels} 声道 | 采样率: ${decoded.sampleRate} Hz | 比特率: ${decoded.bitrate} bps | 时长: ${decoded.duration.toFixed(3)} s`)
    console.log(`  实测电平: Peak = ${metrics.peakDbfs} dBFS | RMS = ${metrics.rmsDbfs} dBFS`)

    const expectedDuration = 1.045
    const expectedPeak = -4.03
    const expectedRms = -22.86

    const durDiff = Math.abs(decoded.duration - expectedDuration)
    const peakDiff = Math.abs(metrics.peakDbfs - expectedPeak)
    const rmsDiff = Math.abs(metrics.rmsDbfs - expectedRms)

    console.log(`  时长误差: ${durDiff.toFixed(3)} s (限制 ≤ 0.1 s)`)
    console.log(`  Peak 误差: ${peakDiff.toFixed(2)} dB (限制 ≤ 1.0 dB)`)
    console.log(`  RMS 误差: ${rmsDiff.toFixed(2)} dB (限制 ≤ 1.0 dB)`)

    if (durDiff > 0.1) {
      throw new Error(`MPEG-1 时长误差超标: ${durDiff} s`)
    }
    if (peakDiff > 1.0) {
      throw new Error(`MPEG-1 Peak 误差超标: ${peakDiff} dB`)
    }
    if (rmsDiff > 1.0) {
      throw new Error(`MPEG-1 RMS 误差超标: ${rmsDiff} dB`)
    }

    console.log('  ✔ [PASS] MPEG-1 解码电平与时长比对测试通过！\n')
  } finally {
    try { unlinkSync(testMp3Path) } catch (_) {}
  }
}

async function testMpeg2() {
  console.log('--- [测试 3/3] MPEG-2 Layer 3 (24kHz 128kbps) 验收比对测试 ---')
  const mp3Buf = Buffer.from(SAMPLE_MPEG2_B64, 'base64')
  const testMp3Path = join(tmpdir(), `selftest_sample_mpeg2_${Date.now()}.mp3`)
  writeFileSync(testMp3Path, mp3Buf)

  try {
    const t0 = performance.now()
    const decoded = decodeMp3(mp3Buf)
    const t1 = performance.now()
    const metrics = computeAcousticMetrics(decoded.samples, decoded.sampleRate)

    console.log(`  解码耗时: ${(t1 - t0).toFixed(2)} ms`)
    console.log(`  格式: ${decoded.channels} 声道 | 采样率: ${decoded.sampleRate} Hz | 比特率: ${decoded.bitrate} bps | 时长: ${decoded.duration.toFixed(3)} s`)
    console.log(`  实测电平: Peak = ${metrics.peakDbfs} dBFS | RMS = ${metrics.rmsDbfs} dBFS`)

    // 验收真值要求：
    // 时长: 6.05 s (误差 <= 0.1s)
    // 峰值: -5.0 dBFS (误差 <= 1.0 dB)
    // RMS: -22.7 dBFS (误差 <= 1.0 dB)
    const expectedDuration = 6.05
    const expectedPeak = -5.0
    const expectedRms = -22.7

    const durDiff = Math.abs(decoded.duration - expectedDuration)
    const peakDiff = Math.abs(metrics.peakDbfs - expectedPeak)
    const rmsDiff = Math.abs(metrics.rmsDbfs - expectedRms)

    console.log(`  采样率检查: ${decoded.sampleRate} Hz (必须为原始 24000 Hz)`)
    console.log(`  时长误差: ${durDiff.toFixed(3)} s (限制 ≤ 0.1 s)`)
    console.log(`  Peak 误差: ${peakDiff.toFixed(2)} dB (限制 ≤ 1.0 dB)`)
    console.log(`  RMS 误差: ${rmsDiff.toFixed(2)} dB (限制 ≤ 1.0 dB)`)

    if (decoded.sampleRate !== 24000) {
      throw new Error(`采样率错误: 期望 24000 Hz，实际为 ${decoded.sampleRate} Hz`)
    }
    if (durDiff > 0.1) {
      throw new Error(`MPEG-2 时长误差超标: ${durDiff} s`)
    }
    if (peakDiff > 1.0) {
      throw new Error(`MPEG-2 Peak 误差超标: ${peakDiff} dB`)
    }
    if (rmsDiff > 1.0) {
      throw new Error(`MPEG-2 RMS 误差超标: ${rmsDiff} dB`)
    }

    console.log('  ✔ [PASS] MPEG-2 解码电平与时长比对测试通过！\n')
  } finally {
    try { unlinkSync(testMp3Path) } catch (_) {}
  }
}

async function main() {
  console.log('========================================')
  console.log('   dsha-tool-audio 插件全功能自测试     ')
  console.log('========================================\n')

  await testWav()
  await testMpeg1()
  await testMpeg2()

  console.log('========================================')
  console.log('   🎉 全部自测试项目均验证通过 (PASS)  ')
  console.log('========================================')
}

main().catch(err => {
  console.error('[FAIL] 自测试失败:', err)
  process.exit(1)
})
